"""Contact sheet for substitute teachers."""

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _fields(student: Student) -> tuple:
    if not student.email:
        name = student.display_name
        raise ProjectError(f"No email for {name}")
    return (student.display_name, student.section,
            student.email)


def _line(row: tuple, widths: list) -> str:
    cells = zip(row, widths)
    return "  ".join(c.ljust(w) for c, w in cells).rstrip()


def format_contacts(students: list) -> list:
    """Rows of name, section and email, sorted by name."""
    if not students:
        raise ProjectError("No students to list")
    ordered = sorted(students, key=lambda s: s.display_name)
    rows = [_fields(s) for s in ordered]
    widths = [max(map(len, col)) for col in zip(*rows)]
    return [_line(row, widths) for row in rows]

