import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import format_contacts


def _student(last, first, section, email):
    return Student("1", last, first, section, email)


class ContactTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = format_contacts([
            _student("Zed", "Al", "B", "al@x.org"),
            _student("Ames", "Bo", "A", "bo@x.org")
        ])
        self.assertEqual(rows, [
            "Ames, Bo  A  bo@x.org",
            "Zed, Al   B  al@x.org"
        ])

    def test_missing_email_names_the_student(self):
        bad = _student("Ames", "Bo", "A", None)
        with self.assertRaises(ProjectError) as ctx:
            format_contacts([bad])
        self.assertIn("Ames, Bo", str(ctx.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            format_contacts([])
